INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('93c7e138-b527-4d3d-962e-df7b7447184a', '051b209e-9985-44da-a832-ca884783cb98', 6, 'A Coragem do Não', NULL, '{"intro": "A incapacidade de dizer n\u00e3o \u00e9 falta de identidade.", "prayer": "Pe\u00e7a for\u00e7a para sustentar suas escolhas.", "practice": "Diga n\u00e3o a algo que rouba o seu tempo hoje.", "reflection": "Dizer sim a tudo \u00e9 dizer n\u00e3o a si mesmo.", "journal_prompt": "A quem voc\u00ea est\u00e1 tentando agradar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;